#!/usr/bin/env python3
"""Require the committed v1 schema generated by Room/KSP (never a hand-written fixture)."""
import json
import subprocess
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
relative = "app/schemas/ru.forma.app.FormaDatabase/1.json"
path = root / relative


def fail(message: str) -> None:
    print("FORMA Room schema FAIL: " + message, file=sys.stderr)
    raise SystemExit(1)


if not path.is_file():
    fail("Room/KSP did not generate " + relative + "; check schemaLocation and exportSchema")

try:
    source = path.read_text(encoding="utf-8")
    schema = json.loads(source)
except (OSError, UnicodeError, ValueError) as exc:
    fail("invalid compiler-generated JSON: " + str(exc))

database = schema.get("database", {})
entities = database.get("entities", [])
if database.get("version") != 1 or not database.get("identityHash"):
    fail("schema version or identityHash is missing")
if len(entities) != 1 or entities[0].get("tableName") != "profiles":
    fail("v1 must contain exactly the original profiles table")
if {f.get("fieldPath") for f in entities[0].get("fields", [])} != {"id", "name", "document"}:
    fail("v1 profiles columns unexpectedly changed")
if entities[0].get("primaryKey", {}).get("columnNames") != ["id"]:
    fail("v1 profile ID primary key changed")

tracked = subprocess.run(["git", "ls-files", "--error-unmatch", "--", relative],
                         cwd=root, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
if tracked.returncode != 0:
    # First KSP-enabled CI pass is a controlled SOURCE-ONLY evidence gate.
    # Print the exact generated text once so it can be committed verbatim.
    print("FORMA_ROOM_SCHEMA_BEGIN")
    print(source, end="" if source.endswith("\n") else "\n")
    print("FORMA_ROOM_SCHEMA_END")
    fail("commit the above compiler-generated v1 schema unchanged before FULL CI")

diff = subprocess.run(["git", "diff", "--exit-code", "--", relative],
                      cwd=root, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
if diff.returncode != 0:
    fail("compiler output differs from committed v1 baseline")
print("FORMA Room schema PASS: compiled v1 matches tracked baseline")
